import { FC, HTMLAttributes, ReactElement } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, theme, Typography } from 'antd';
import cn from 'classnames';

import coinImage from 'assets/images/coin.webp';
import ClockTimerIcon from 'assets/images/icons/clock-timer.svg?react';
import { useMedia } from 'shared/hooks';
import { formatNumber } from 'shared/utils';

import styles from './BalanceItem.module.scss';

interface IBalanceItemProps extends HTMLAttributes<HTMLDivElement> {
	balance: string;
	currency: string;
	type: 'available' | 'hold';
	currenciesMap: Record<string, string>;
	reportsLink?: string;
}

interface IType {
	balanceImg?: string;
	colorBalance: string;
	colorText: string;
	textIcon?: ReactElement;
	title: string;
}

export const BalanceItem: FC<IBalanceItemProps> = ({ className, balance, currency, type, currenciesMap, ...props }) => {
	const { t } = useTranslation();
	const isMobile = useMedia();
	const {
		token: { colorPrimaryTextHover, colorTextTertiary, colorTextSecondary },
	} = theme.useToken();

	const types: Record<typeof type, IType> = {
		available: {
			balanceImg: coinImage,
			colorBalance: colorPrimaryTextHover,
			colorText: colorTextSecondary,
			title: t('Средства, доступные для вывода'),
		},
		hold: {
			colorBalance: colorTextTertiary,
			colorText: colorTextTertiary,
			textIcon: <ClockTimerIcon />,
			title: t('Средства в обработке'),
		},
	};

	return (
		<div {...props} className={cn(className, styles.balanceItem, styles[type])}>
			<div className={styles.info}>
				<Flex gap={8} align="center">
					{!!types[type].balanceImg && <img src={types[type].balanceImg} alt="" height={26} />}
					<Typography.Title level={3} className={styles.balance} style={{ color: types[type].colorBalance, margin: 0 }}>
						{isMobile && currenciesMap[currency]} {formatNumber(balance)} {!isMobile && currency}
					</Typography.Title>
				</Flex>
				<Typography.Text className={styles.title} style={{ color: types[type].colorText }}>
					<Flex gap={4} align="center">
						{types[type].textIcon}
						{types[type].title}
					</Flex>
				</Typography.Text>
			</div>
		</div>
	);
};
